        return [clamp_step(bx - ax), clamp_step(by - ay)]

    def step_away(a, b):
        ax, ay = a
        bx, by = b
        return [clamp_step(ax - bx), clamp_step(ay - by)]

    def manhattan(p, q):
        return abs(p[0] - q[0]) + abs(p[1] - q[1])

    def nearest_point(points, ref):
        best = None
        best_d = None
        for p in points:
