    if env == "territory_control":
        candidates = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        target = nearest_point(candidates, self_pos)
        if target is not None:
            return step_toward(self_pos, target)
        # If no explicit targets, pressure opponent or spread outward.
        if manhattan(self_pos, opp_pos) <= 2:
            return step_away(self_pos, opp_pos)
        gx = observation.get("grid_width", 0)
        gy = observation.get("grid_height", 0)
        center = (gx // 2, gy // 2)
        if gx and gy:
            return step_toward(self_pos, center)
        return [0, 0]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = nearest_point(resources, self_pos)
    if target is not None:
        # Prefer resources; if adjacent to opponent and not on resource, avoid conflict.
        if manhattan(self_pos, opp_pos) <= 1 and manhattan(target, self_pos) > 1:
            return step_away(self_pos, opp_pos)
        return step_toward(self_pos, target)

